Lemma zlength_app : forall {A} (l1 l2 : list A), zlength (l1 ++ l2) = zlength l1 + zlength l2.
Proof. intros. unfold zlength. rewrite length_app. lia. Qed.
Lemma zlength_firstn : forall {A} (k : nat) (l : list A), (k <= length l)%nat -> zlength (firstn k l) = Z.of_nat k.
Proof. intros. unfold zlength. rewrite length_firstn. lia. Qed.

(* [comment removed for export] *)
Definition fb_commit (FB : fbv) (k : Z) : fbv := mkFB (fb_begin FB) (fb_in FB) (fb_out FB + k) (fb_last FB) (fb_end FB).

(* [comment removed for export] *)
Definition w_after_read (w : rsw) (k : Z) : rsw :=
  mkW (w_d w) (w_PB w) (w_FBB w) (fb_commit (w_FB w) k) (w_fds w ++ firstn (Z.to_nat k) (w_sds w))
      (if zlength (w_sds w) =? 0 then w_Fs w else fb_consume (w_Fs w) k) (skipn (Z.to_nat k) (w_sds w)) (w_nr w + 1).

(* [comment removed for export] *)
Definition pst_eof (d : pst) : pst :=
  mkPST (rs_eof_c (ps_c d)) (ps_S d) (ps_L d) (ps_ns d) (ps_ls d) (ps_em d) (ps_h d) (ps_u d) (ps_es d) (ps_insz d) (rs_eof_g (ps_c d) (ps_g d)) (ps_rdi d)
        (ps_LBn d) (ps_st d) (ps_errv d).
Definition w_after_eof (w : rsw) : rsw :=
  mkW (pst_eof (w_d w)) (w_PB w) (w_FBB w) (w_FB w) (w_fds w) (w_Fs w) (w_sds w) (w_nr w).

Lemma rs_eof_c_cases : forall c, rs_eof_c c = c \/ rs_eof_c c = pc_set_state c 11.
Proof.
  intros c. unfold rs_eof_c, peof_res. destruct (pc_state c =? 0); [left; reflexivity|].
  destruct (pc_state c <=? 2); [left; reflexivity|]. destruct (peof_body_flags c); [| right; reflexivity].
  destruct (pc_state c =? 11); left; reflexivity.
Qed.

