(* [comment removed for export] *)
Definition rs_at_cmp (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (eof : bool) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (tot k : Z) (j8 : list byte) (t1c optc : list cell),
    cfg_ms cf = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -128)) (c_gp C) (c_tp C) t0 t1 t2 (wz tot) (wz (c_P C + O_H_EC)) (wz (if eof then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                     (wz (c_P C)) (wz (c_P C + O_H_FB)) (wz (c_P C + O_H_STREAM)) (wz k) (wz G_MISC_CAT_INST) (wz CAT_ID_SYSGEN_SHR1)
                     (c_s8 C) (c_s9 C) (c_s10 C) (c_s11 C) t3 t4 t5 t6)
                (c_F C) (Z_to_bv 64 RS_CMP) (c_fc C) None m (seg_rom usegs)
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w (if eof then EC_ts_eof else EC_clear) m /\ RWp H C w /\ stk usegs m (c_lo C) (bv_unsigned sp + -128)
    /\ rs_frames m sp j8 t1c optc s7v s6v s5v s4v s3v s2v s1v s0v ra fr0
    /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m
    /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
    /\ wM (c_N C) w <= M0
    /\ (if eof then w_sds w = [] /\ k = 0
        else 1 <= k /\ k <= fb_size (w_FB w) /\ fb_in (w_FB w) <= fb_out (w_FB w) /\ wM (c_N C) w < M0 /\ w_nr w <= c_N C - zlength (w_sds w)).

(* [comment removed for export] *)
Lemma rs_read_B1 : forall (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (n : Z) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 ->
  rs_at_dbpret H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w n cf ->
  hs_SR H (fun cf' => exists eof, rs_at_cmp C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 (w_after_read w (rs_take (w_sds w) n)) eof cf') cf.
Proof.
  intros C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w n cf STC SPE AT.
  pose proof STC as STC0.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s8w s9w s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn st errv].
  destruct cf as [ms mo]. unfold rs_at_dbpret, rs_core, rs_frames, RWm, rs_static in *. cbn_w_all. cbn [cfg_ms cfg_model] in AT.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP & MB1).
  destruct AT as (t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & s5x & s6x & s7x & t3 & t4 & t5 & t6 & m & tot & j8 & j7 & t1c
                  & -> & NS11 & KREL & MP & (RM & RP & ST & (FRM & FRhi & FR0 & LFR0) & XP0 & TOT0 & TOT & NRB) & LAST & NR & NE & DJS & DJF & WM0).
  destruct RM as (PC & UW & RDI & J13 & J32a & J8a & J32b & J8b & HC & FTS & MV & FBU & EC & BS & SB & HP & ERR & AUX & MI).
  pose proof RP as RP0. unfold RWp in RP. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM_ & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  assert (LOP : lo + 13136 <= P) by (clear - LO; unfold SRO_STACK in LO; lia).
  hcb. pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  subst tp.
  pose proof (FlatBuf_shape _ _ _ _ _ FBU) as (FS1 & FS2 & FS3 & FS4 & FS5). pose proof (FlatBuf_size _ _ _ _ _ FBU) as FSZ.
  destruct FS5 as [K | (BP & BAL & BCP & BQLO & pf0 & INf0)]; [exfalso; exact (NE K)|]. unfold fb_cap in BCP.
  destruct FRM as (F8 & T1 & SZT1 & OPT & _).
  pose proof UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS).
  pose proof RBS as (RB1 & RB2 & RB3 & RB4 & RB5). unfold SZ_SPCI_STATE in RB4, RB5, DJS.
  pose proof SB as (pS & j7S & j16S & j4S & _ & _ & _ & _ & _ & _ & _ & _ & FBs & _).
  pose proof (FlatBuf_shape _ _ _ _ _ FBs) as (SS1 & SS2 & SS3 & SS4 & SS5). cbn [st_fb] in SS1, SS2, SS3, SS4, SS5. clear FBs pS j7S j16S j4S.
  assert (KR : 0 <= rs_take sds n <= n /\ rs_take sds n <= zlength sds) by (unfold rs_take; unfold zlength; clear - NR; lia).
  (* [comment removed for export] *)
  pose proof FBU as (FBC & FOK2 & _ & BLK). destruct (BLK NE) as (pre & junk & BCH). clear BLK.
  pose proof BCH as [[WFB _] _]. cbn in WFB. destruct WFB as (Lpre & Lfds & Ljunk & _).
  change ([CB (Z.to_nat (fb_in FB - fb_begin FB)) pre; CB (length fds) fds; CB (Z.to_nat (fb_end FB - fb_out FB)) junk])
