Lemma rs_done_mono : forall (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M1 M0 : Z) (cf : config),
  rs_done H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 cf -> M1 <= M0 ->
  rs_done H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 cf.
Proof.
  intros C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 M0 cf D LE. unfold rs_done in *.
  destruct D as (t0 & t1 & t2 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m & w & E & tot & D).
  exists t0, t1, t2, a1, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m, w, E, tot.
  destruct D as (D1 & D2 & D3 & D4 & D5 & D6 & D7 & D8 & D9 & D10 & D11 & D12 & D13 & D14).
  repeat (split; [assumption|]). split; [clear - D13 LE; lia|].
  intros K1 K2. destruct (D14 K1 K2) as [K3 K4]. split; [clear - K3 LE; lia | exact K4].
Qed.

Lemma rs_read_round : forall (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 ->
  rs_at_doread H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf ->
  hs_SR H (fun cf' => rs_done H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 cf'
                      \/ exists M1 w', M1 < M0 /\ rs_at_put H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 w' cf') cf.
Proof.
  intros C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf STC SPE AT.
  eapply (hh_seq H HH); [exact (rs_read_A H HH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ STC SPE AT)|].
  intros cf1 (w1 & n & _ & AT1).
  eapply (hh_seq H HH); [exact (rs_read_B1 _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ STC SPE AT1)|].
  intros cf2 (eof & AT2). exact (rs_read_B2 _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ STC SPE AT2).
Qed.

Lemma rs_loop : forall (n : nat) (C : rsc) (sp : word) (s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 -> M0 < Z.of_nat n ->
  rs_at_doread H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf ->
  hs_SR H (rs_done H C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0) cf.
Proof.
  induction n as [|n IH]; intros C sp s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w cf STC SPE LT AT.
  - exfalso. pose proof AT as AT'. unfold rs_at_doread, rs_core in AT'.
    destruct AT' as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & s5x & s6x & s7x & t3 & t4 & t5 & t6 & m & E & tot & j8 & t1c & t2c
                     & _ & _ & _ & _ & _ & WM0).
    destruct STC as (_ & _ & _ & _ & _ & _ & _ & NR26 & _). unfold wM in WM0. clear - WM0 NR26 LT. unfold zlength in WM0. cbn in LT. nia.
  - eapply (hh_seq H HH); [exact (rs_read_round _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ STC SPE AT)|].
    intros cf1 [D | (M1 & w1 & LT1 & AP)]; [apply (hh_done H HH); exact D|].
    eapply (hh_seq H HH); [exact (rs_put_round H HH PUT _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ STC SPE AP)|].
    intros cf2 [D | (w2 & _ & AD)]; [apply (hh_done H HH); eapply rs_done_mono; [exact D | clear - LT1; lia]|].
    eapply (hh_mono H HH); [eapply (IH _ _ _ _ _ _ _ _ _ _ _ _ M1 w2); [exact STC | exact SPE | clear - LT LT1; lia | exact AD]|].
    intros cf3 D. eapply rs_done_mono; [exact D | clear - LT1; lia].
Qed.
